from typing import List

class Solution:
    def countValidSelections(self, nums: List[int]) -> int:
        n = len(nums)
        ans = 0

        def simulate(start_idx, direction):
            # direction: -1 for left, 1 for right
            curr = start_idx
            arr = list(nums)  # copy to avoid side effects

            while True:
                if curr < 0 or curr >= n:
                    return 1 if all(x == 0 for x in arr) else 0

                val = arr[curr]
                if val == 0:
                    if direction == -1:
                        curr -= 1
                    else:
                        curr += 1
                else:
                    arr[curr] -= 1
                    direction = -direction
                    if direction == -1:
                        curr -= 1
                    else:
                        curr += 1

            return 1 if all(x == 0 for x in arr) else 0

        for i in range(n):
            if nums[i] == 0:
                if simulate(i, -1):
                    ans += 1
                if simulate(i, 1):
                    ans += 1

        return ans

from typing import List

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        # If there's any element less than k, it's impossible to make all elements equal to k
        # because we can only reduce values, not increase them.
        if min(nums) < k:
            return -1

        # Count the number of unique elements strictly greater than k.
        # Each unique value > k requires one operation to reduce it to the next lower value,
        # and finally one operation to reduce the remaining values to k.
        # However, note that the number of operations is exactly the count of unique values > k.
        unique_greater = set()
        for x in nums:
            if x > k:
                unique_greater.add(x)

        return len(unique_greater)

import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        # Helper function to check if a number is prime
        def is_prime(num):
            if num < 2:
                return False
            if num == 2:
                return True
            if num % 2 == 0:
                return False
            i = 3
            while i * i <= num:
                if num % i == 0:
                    return False
                i += 2
            return True

        # If the start or target number is prime, it's impossible
        if is_prime(n) or is_prime(m):
            return -1

        # Priority queue stores tuples (current_total_cost, current_number)
        pq = []
        # Initial cost includes the starting value n as per the problem description
        heapq.heappush(pq, (n, n))
        # Dictionary to store the minimum cost to reach each number
        dist = {n: n}

        while pq:
            cost, curr = heapq.heappop(pq)

            # If we reached the target m, return the accumulated cost
            if curr == m:
                return cost

            # Convert current number to a list of digits to perform operations
            s_curr = str(curr)
            digits = [int(c) for c in s_curr]
            length = len(s_curr)

            for i in range(length):
                # Try increasing the digit at index i
                # Rule: Choose any digit from n that is not 9 and increase it by 1
                if digits[i] < 9:
                    new_digits = list(digits)
                    new_digits[i] += 1

                    # Construct the new number string, stripping leading zeros
                    new_val_str = "".join(map(str, new_digits)).lstrip('0')
                    if not new_val_str:
                        new_val_str = "0"
                    new_num = int(new_val_str)

                    # Ensure the new number is not prime
                    if not is_prime(new_num):
                        new_cost = cost + new_num
                        if new_num not in dist or new_cost < dist[new_num]:
                            dist[new_num] = new_cost
                            heapq.heappush(pq, (new_cost, new_num))

                # Try decreasing the digit at index i
                # Rule: Choose any digit from n that is not 0 and decrease it by 1
                if digits[i] > 0:
                    new_digits = list(digits)
                    new_digits[i] -= 1

                    new_val_str = "".join(map(str, new_digits)).lstrip('0')
                    if not new_val_str:
                        new_val_str = "0"
                    new_num = int(new_val_str)

                    # Ensure the new number is not prime
                    if not is_prime(new_num):
                        new_cost = cost + new_num
                        if new_num not in dist or new_cost < dist[new_num]:
                            dist[new_num] = new_cost
                            heapq.heappush(pq, (new_cost, new_num))

        return -1

