import heapq
from typing import List

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        # Sieve of Eratosthenes up to 10000
        LIMIT = 10000
        is_prime = [True] * (LIMIT + 1)
        is_prime[0] = is_prime[1] = False
        for i in range(2, int(math.sqrt(LIMIT)) + 1):
            if is_prime[i]:
                for j in range(i*i, LIMIT + 1, i):
                    is_prime[j] = False

        # If start or end is prime, impossible
        if is_prime[n] or is_prime[m]:
            return -1

        # If n == m, cost is 0
        if n == m:
            return 0

        # Precompute powers of 10 for digit positions
        len_digits = len(str(n))
        powers = [10**i for i in range(len_digits)]

        # Dijkstra's algorithm
        dist = {n: n}
        pq = [(n, n)]  # (current_value, accumulated_cost)

        visited = {n}

        while pq:
            curr, cost = heapq.heappop(pq)

            if curr == m:
                return cost

            s_curr = str(curr)
            num_digits = len(s_curr)

            if num_digits != len_digits:
                continue

            # Try increasing each digit
            for i in range(num_digits):
                d = int(s_curr[i])
                if d < 9:
                    add_val = powers[i]
                    next_val = curr + add_val
                    if next_val <= LIMIT and not is_prime[next_val] and next_val not in visited:
                        dist[next_val] = cost + next_val
                        heapq.heappush(pq, (next_val, dist[next_val]))
                        visited.add(next_val)

            # Try decreasing each digit
            for i in range(num_digits):
                d = int(s_curr[i])
                if d > 0:
                    sub_val = powers[i]
                    next_val = curr - sub_val
                    # Must stay within same digit length and >= 1
                    if next_val >= 10**(num_digits - 1) and not is_prime[next_val] and next_val not in visited:
                        dist[next_val] = cost + next_val
                        heapq.heappush(pq, (next_val, dist[next_val]))
                        visited.add(next_val)

        return -1
